(()=>{'use strict';const G=MartinsGastosObras,F=MartinsFinanceiro,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);if(!$('view-gestao'))return;
const css=document.createElement('style');css.textContent='.mf-box{background:white;border:1px solid #e2e8f0;border-radius:12px;padding:18px;color:#334155}.mf-box h2{font-weight:800;font-size:21px}.mf-box h3{font-weight:800;font-size:17px}.mf-box label,#fin-dialog label{display:block;font-weight:700;font-size:12px;margin:10px 0}.mf-box input,.mf-box select,#fin-dialog input{box-sizing:border-box;max-width:100%;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:8px;background:white}.mf-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.mf-box button,#fin-dialog button{min-height:44px;background:#0f172a;color:#fbbf24;border-radius:8px;padding:10px 12px;font-weight:700;font-size:12px;margin:5px 5px 5px 0}.mf-box button[aria-pressed=true]{background:#f59e0b;color:#0f172a}.mf-box p,#fin-dialog p{font-size:12px;line-height:1.6}.mf-box td,.mf-box th{padding:9px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:12px}.mf-scroll{overflow:auto}.mf-message{color:#92400e;white-space:pre-wrap}.mf-box [hidden],#fin-dialog [hidden]{display:none!important}#fin-dialog{width:min(600px,calc(100vw - 20px));max-height:88vh;overflow:auto;padding:20px;border:1px solid #cbd5e1;border-radius:14px}#fin-dialog::backdrop{background:#020617bb}#fin-review{white-space:pre-wrap}#fin-drawer{border-top:1px solid #e2e8f0;padding:12px;margin-top:8px}#fin-drawer h4{font-weight:900;font-size:12px;color:#0f172a}#fin-drawer button{display:block;width:100%;text-align:left;min-height:44px;font-size:12px;font-weight:700;padding:10px;color:#334155}@media(max-width:500px){.mf-grid{grid-template-columns:1fr}}@media print{#view-financeiro,#subview-gastos,#fin-dialog{display:none!important}}';document.head.append(css);
const finance=document.createElement('section');finance.id='view-financeiro';finance.className='mf-box hidden';finance.innerHTML=`<h2>Financeiro</h2><p>Caixa local: registros manuais. Nenhuma movimentação bancária é executada. Gastos de uma obra são consultados separadamente na Gestão da Obra.</p><nav aria-label="Áreas do Financeiro"><button id="fin-tab-contas" type="button">Cadastrar contas</button><button id="fin-tab-fluxo" type="button">Fluxo de caixa</button><button id="fin-tab-vencimentos" type="button">Contas a pagar / receber</button></nav><p id="fin-status" class="mf-message" role="status" aria-live="polite"></p><div id="fin-area-contas" hidden><h3>Contas de caixa / banco</h3><p>Cadastre o nome de referência da conta. Não informe senhas ou dados de acesso bancário.</p><div class="mf-grid"><label>Nome da conta<input id="fin-account-name" maxlength="120" placeholder="Ex.: Caixa da empresa"></label><label>Tipo de conta<select id="fin-account-type"><option>Caixa</option><option>Banco</option><option>Outros</option></select></label></div><label id="fin-bank-label">Banco da conta<select id="fin-account-bank"><option value="">Selecione</option><option>Banco do Brasil</option><option>Caixa Econômica Federal</option><option>Bradesco</option><option>Itaú</option><option>Santander</option><option>Nubank</option><option>Inter</option><option>Sicoob</option><option>Sicredi</option><option>Outro</option></select></label><label id="fin-bank-other-label" hidden>Nome do outro banco<input id="fin-account-bank-other" maxlength="120"></label><button type="button" id="fin-back-entry" hidden>Voltar ao lançamento sem perder preenchimento</button><button type="button" id="fin-account-save">Conferir nova conta</button><div id="fin-account-list"></div></div><div id="fin-area-fluxo" hidden><h3>Fluxo de caixa</h3><div class="mf-grid"><label>Tipo da consulta<select id="fin-filter-type"><option value="despesa">Despesas</option><option value="receita">Receitas</option></select></label><label>Empresa<select id="fin-filter-company"></select></label><label>Obra da consulta<select id="fin-filter-work"></select></label><label>Categoria da consulta<select id="fin-filter-category"></select></label><label>Centro de custo da consulta<select id="fin-filter-center"></select></label><label>De — data do lançamento<input id="fin-from" type="date"></label><label>Até — data do lançamento<input id="fin-to" type="date"></label></div><label>Fornecedor / favorecido / cliente<input id="fin-filter-payee" maxlength="500" placeholder="Parte do nome"></label><button type="button" id="fin-refresh">Atualizar</button><button type="button" id="fin-export">Exportar CSV do filtro</button><p id="fin-totals"></p><div class="mf-scroll"><table><thead><tr><th>Data / vencimento</th><th>Empresa / favorecido</th><th>Descrição / categoria</th><th>Conta / situação</th><th>Valor</th><th>Obra / centro de custo / histórico</th><th>Ações</th></tr></thead><tbody id="fin-rows"></tbody></table></div><details id="fin-new"><summary style="padding:15px;cursor:pointer;font-weight:800">+ Lançar despesa ou receita</summary><div class="mf-grid"><label>Tipo do lançamento<select id="fin-type"><option value="despesa">Despesa / conta a pagar</option><option value="receita">Receita / conta a receber</option></select></label><label>Situação<select id="fin-state"><option value="pendente">Pendente</option><option value="pago">Pago / recebido</option></select></label><label>Data do lançamento<input id="fin-date" type="date"></label><label>Vencimento<input id="fin-due-date" type="date"></label><label>Pago / recebido em<input id="fin-paid-date" type="date"></label><label>Empresa responsável<input id="fin-company" maxlength="500"></label><label>Favorecido / origem<input id="fin-payee" maxlength="500"></label><label>Categoria<select id="fin-category"></select></label><label>Conta de caixa / banco<select id="fin-account"></select></label><label>Valor total (R$)<input id="fin-value" type="number" step="0.01" min="0.01" inputmode="decimal"></label><label>Descrição<input id="fin-description" maxlength="500"></label></div><button type="button" id="fin-quick-account">+ Cadastrar conta</button><h3 style="margin-top:15px">Destino do lançamento</h3><label>Distribuição<select id="fin-allocation-mode"><option value="unica">Uma obra ou administração</option><option value="rateio">Ratear entre obras</option></select></label><div id="fin-single"><label>Obra<select id="fin-work"></select></label><label>Centro de custo<input id="fin-center" list="fin-centers" maxlength="500" placeholder="Ex.: Fundação, Mão de obra, Instalações"></label><p id="fin-work-hint">Sem obra: o lançamento pertence à administração.</p></div><div id="fin-multiple" hidden><p>Informe obra, centro de custo e valor de cada parcela. A soma deve fechar o total.</p><div id="fin-allocations"></div><button type="button" id="fin-add-allocation">+ Adicionar obra ao rateio</button></div><button type="button" id="fin-prepare">Conferir lançamento</button></details></div><div id="fin-area-vencimentos" hidden><h3>Contas a pagar / receber</h3><p>Somente lançamentos pendentes. Período por vencimento; registros antigos sem vencimento ficam identificados.</p><div class="mf-grid"><label>Contas<select id="fin-due-type"><option value="despesa">A pagar</option><option value="receita">A receber</option></select></label><label>Situação do vencimento<select id="fin-due-state"><option value="todos">Todas as pendentes</option><option value="vencido">Vencidas</option><option value="hoje">Vencem hoje</option><option value="futuro">A vencer</option><option value="semData">Sem vencimento informado</option></select></label><label>Vencimento de<input id="fin-due-from" type="date"></label><label>Vencimento até<input id="fin-due-to" type="date"></label></div><label>Fornecedor / favorecido / cliente<input id="fin-due-payee" maxlength="500" placeholder="Parte do nome"></label><button type="button" id="fin-new-bill">+ Criar conta a pagar / receber</button><button type="button" id="fin-due-refresh">Atualizar vencimentos</button><p id="fin-due-totals"></p><div class="mf-scroll"><table><thead><tr><th>Vencimento / situação</th><th>Empresa / favorecido</th><th>Descrição</th><th>Valor</th><th>Ações</th></tr></thead><tbody id="fin-due-rows"></tbody></table></div></div><datalist id="fin-centers"><option>Materiais</option><option>Mão de obra</option><option>Equipamentos</option><option>Serviços</option><option>Fundação</option><option>Instalações</option><option>Administrativo</option></datalist>`;$('view-gestao').after(finance);
const workPanel=document.createElement('section');workPanel.id='subview-gastos';workPanel.className='mf-box hidden';workPanel.innerHTML='<h3>Gastos com a obra</h3><p id="wg-name"></p><p>Consulta dos lançamentos de despesa vinculados à obra selecionada na Gestão. Somente a parcela desta obra entra no total. Lançamentos são feitos no Financeiro.</p><div class="mf-grid"><label>Empresa<select id="wg-company"></select></label><label>Centro de custo<select id="wg-center"></select></label><label>De — data do lançamento<input id="wg-from" type="date"></label><label>Até — data do lançamento<input id="wg-to" type="date"></label></div><button type="button" id="wg-refresh">Atualizar gastos</button><button type="button" id="wg-export">Exportar gastos CSV</button><p id="wg-status" class="mf-message" role="status"></p><p id="wg-totals"></p><p id="wg-groups"></p><div class="mf-scroll"><table><thead><tr><th>Data / empresa</th><th>Favorecido / descrição</th><th>Centro de custo</th><th>Situação</th><th>Valor nesta obra</th></tr></thead><tbody id="wg-rows"></tbody></table></div>';$('subview-custos').after(workPanel);
const tab=document.createElement('button');tab.id='subtab-btn-gastos';tab.type='button';tab.textContent='💰 Gastos com a obra';tab.className='subtab-btn px-3 py-1.5 text-xs font-medium text-slate-600 rounded-md';$('subtab-btn-custos').after(tab);
const dialog=document.createElement('dialog');dialog.id='fin-dialog';dialog.setAttribute('aria-label','Conferir operação financeira');dialog.innerHTML='<h3 style="font-weight:800">Conferir operação</h3><p id="fin-review"></p><label id="fin-reason-label" hidden>Motivo do cancelamento<input id="fin-reason" maxlength="500"></label><label id="fin-payment-label" hidden>Pago / recebido em<input id="fin-payment" type="date"></label><p id="fin-dialog-status" role="status" class="mf-message"></p><button type="button" id="fin-confirm">Confirmar registro</button><button type="button" id="fin-back">Voltar sem alterar</button>';document.body.append(dialog);
const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),br=s=>s?s.split('-').reverse().join('/'):'Não informado',today=()=>new Date().toLocaleDateString('en-CA'),works=()=>Object.keys(dadosObras),legacy='Sem centro de custo (anterior)';let active='fluxo',ledger=null,accountBase=null,flowReport=null,workReport=null,request=null,busy=false;
function actor(scope='financeiro'){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!(scope==='obra'?F.canReadWork(u):G.canManage(u))||!session||!id(u)||id(u)!==id(session)||u.perfil!==session.perfil||session.status==='Inativo')throw Error(scope==='obra'?'Acesso aos gastos da obra restrito à Gestão / Engenharia autorizada.':'Acesso ao Financeiro restrito a perfil autorizado.');return u.usuario||u.email||u.nome;}
function readLedger(){const s=P.snapshot(localStorage,G.KEY,[]);G.assertRows(s.data);return s;}function readAccounts(){const s=P.snapshot(localStorage,F.ACCOUNTS,[]);F.accounts(s.data);return s;}
function opts(select,values,placeholder){const value=select.value;select.replaceChildren();if(placeholder!==undefined)select.add(new Option(placeholder,''));for(const x of values)select.add(new Option(typeof x==='string'?x:x.label,typeof x==='string'?x:x.value));if([...select.options].some(o=>o.value===value))select.value=value;}
function cell(tr,value){const td=document.createElement('td');td.textContent=value;tr.append(td);return td;}function empty(id,cols){if($(id).children.length)return;const tr=document.createElement('tr'),td=cell(tr,'Nenhum lançamento neste filtro.');td.colSpan=cols;$(id).append(tr);}
function allocationText(r){return r.rateios.length?r.rateios.map(x=>x.obra+' → '+(x.centroCusto||legacy)+' · '+money(x.centavos)).join('\n'):'Administração / '+(r.centroCusto||'Administrativo');}
function actionButtons(row,r){if(r.status==='cancelado')return;for(const [status,label] of [['pago',r.tipo==='receita'?'Registrar recebimento':'Registrar pagamento'],['cancelado','Cancelar lançamento']]){if(status==='pago'&&r.status!=='pendente')continue;const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=()=>prepareChange(r.id,status);row.append(b);}}
function renderFlow(){const s=readLedger();opts($('fin-filter-company'),[...new Set(s.data.map(r=>r.empresa))].sort(),'Todas as empresas');opts($('fin-filter-work'),[...new Set([...works(),...s.data.flatMap(r=>r.rateios.map(x=>x.obra))])].sort(),'Todas as obras e administração');opts($('fin-filter-center'),[...new Set(s.data.flatMap(r=>r.rateios.map(x=>x.centroCusto||legacy)))].sort(),'Todos os centros');const report=G.report(s.data,{obra:$('fin-filter-work').value,categoria:$('fin-filter-category').value,centroCusto:$('fin-filter-center').value,tipo:$('fin-filter-type').value,empresa:$('fin-filter-company').value,from:$('fin-from').value,to:$('fin-to').value,favorecido:$('fin-filter-payee').value});$('fin-totals').textContent=($('fin-filter-type').value==='despesa'?'Pago: ':'Recebido: ')+money(report.pago)+' · Pendente: '+money(report.pendente)+' · Cancelado (fora do ativo): '+money(report.cancelado);$('fin-rows').replaceChildren();for(const r of report.rows){const tr=document.createElement('tr');for(const v of [br(r.data)+' / '+br(r.vencimento),r.empresa+' / '+r.favorecido,r.descricao+' / '+r.categoria,r.conta+' / '+r.status+(r.pagoEm?' em '+br(r.pagoEm):''),money(r.valorExibido)+(r.valorExibido!==r.valorCentavos?' / total '+money(r.valorCentavos):'')])cell(tr,v);const info=cell(tr,'');const detail=document.createElement('details'),summary=document.createElement('summary'),p=document.createElement('p');summary.textContent='Obra, centro e histórico';p.style.whiteSpace='pre-wrap';p.textContent=allocationText(r)+'\n'+r.historico.map(h=>h.acao+' por '+h.por+' em '+new Date(h.em).toLocaleString('pt-BR')+(h.motivo?' — '+h.motivo:'')).join('\n');detail.append(summary,p);info.append(detail);actionButtons(cell(tr,''),r);$('fin-rows').append(tr);}empty('fin-rows',7);ledger=s;flowReport=report;}
function renderAccounts(){const s=readAccounts();$('fin-account-list').replaceChildren();for(const c of s.data){const p=document.createElement('p');p.textContent=c.nome+' · '+c.tipo+(c.banco?' · '+c.banco:'');$('fin-account-list').append(p);}if(!s.data.length)$('fin-account-list').textContent='Nenhuma conta cadastrada.';opts($('fin-account'),s.data.map(c=>({label:c.nome+' ('+c.tipo+')',value:c.id})),'Selecione uma conta');accountBase=s;}
function renderDue(){const report=F.due(readLedger().data,{tipo:$('fin-due-type').value,today:today(),from:$('fin-due-from').value,to:$('fin-due-to').value,situacao:$('fin-due-state').value,favorecido:$('fin-due-payee').value});$('fin-due-totals').textContent='Vencidas: '+money(report.vencido)+' · Hoje: '+money(report.hoje)+' · A vencer: '+money(report.futuro)+' · Sem vencimento: '+money(report.semData)+' · Total do filtro: '+money(report.total);$('fin-due-rows').replaceChildren();for(const r of report.rows){const tr=document.createElement('tr');for(const v of [br(r.vencimento)+' / '+({vencido:'Vencida',hoje:'Vence hoje',futuro:'A vencer',semData:'Sem vencimento'}[r.situacaoVencimento]),r.empresa+' / '+r.favorecido,r.descricao,money(r.valorCentavos)])cell(tr,v);actionButtons(cell(tr,''),r);$('fin-due-rows').append(tr);}empty('fin-due-rows',5);}
function refreshFinance(){try{actor();for(const name of ['contas','fluxo','vencimentos']){$('fin-area-'+name).hidden=name!==active;$('fin-tab-'+name).setAttribute('aria-pressed',String(name===active));}renderAccounts();if(active==='fluxo')renderFlow();if(active==='vencimentos')renderDue();opts($('fin-work'),works().sort(),'Sem obra — Administração');$('fin-status').textContent='';}catch(e){ledger=null;flowReport=null;accountBase=null;for(const name of ['contas','fluxo','vencimentos'])$('fin-area-'+name).hidden=true;$('fin-status').textContent=e.message;}}
function renderWork(){workReport=null;try{actor('obra');const obra=$('gestao-obra-select').value;if(!Object.hasOwn(dadosObras,obra))throw Error('Selecione uma obra válida na Gestão');const rows=readLedger().data;$('wg-name').textContent='Obra selecionada: '+obra;const relevant=rows.filter(r=>r.tipo==='despesa'&&r.rateios.some(x=>x.obra===obra));opts($('wg-company'),[...new Set(relevant.map(r=>r.empresa))].sort(),'Todas as empresas');opts($('wg-center'),[...new Set(relevant.flatMap(r=>r.rateios.filter(x=>x.obra===obra).map(x=>x.centroCusto||legacy)))].sort(),'Todos os centros de custo');const report=G.report(rows,{obra,empresa:$('wg-company').value,centroCusto:$('wg-center').value,from:$('wg-from').value,to:$('wg-to').value});$('wg-totals').textContent='Pago: '+money(report.pago)+' · Pendente: '+money(report.pendente)+' · Ativo: '+money(report.pago+report.pendente)+' · Cancelado fora do ativo: '+money(report.cancelado);const centers=new Map;for(const r of report.rows)if(r.status!=='cancelado'){const c=r.rateios.find(x=>x.obra===obra)?.centroCusto||legacy;centers.set(c,(centers.get(c)||0)+r.valorExibido);}$('wg-groups').textContent='Ativo por centro: '+([...centers].map(([k,v])=>k+' '+money(v)).join(' · ')||'nenhum')+' | Por empresa: '+([...report.empresas].map(([k,v])=>k+' '+money(v)).join(' · ')||'nenhuma');$('wg-rows').replaceChildren();for(const r of report.rows){const tr=document.createElement('tr');for(const v of [br(r.data)+' / '+r.empresa,r.favorecido+' / '+r.descricao,r.rateios.find(x=>x.obra===obra)?.centroCusto||legacy,r.status,money(r.valorExibido)])cell(tr,v);$('wg-rows').append(tr);}empty('wg-rows',5);$('wg-status').textContent=report.rows.length+' lançamento(s) da obra. Previsões e consumos estimados não são somados ao caixa.';workReport=report;}catch(e){$('wg-rows').replaceChildren();$('wg-totals').textContent='';$('wg-groups').textContent='';$('wg-status').textContent=e.message;}}
const oldTab=window.setSubtabGestao;window.setSubtabGestao=function(name){oldTab(name);workPanel.classList.toggle('hidden',name!=='gastos');tab.classList.toggle('bg-white',name==='gastos');if(name==='gastos')renderWork();};tab.onclick=()=>window.setSubtabGestao('gastos');tab.parentElement.addEventListener('click',e=>{const b=e.target.closest('.subtab-btn');if(b&&b!==tab){workPanel.classList.add('hidden');tab.classList.remove('bg-white');}});
const oldNav=window.navegarParaSecao;window.navegarParaSecao=function(name,sub){if(name==='financeiro'){oldNav(name);finance.classList.remove('hidden');active=['contas','fluxo','vencimentos'].includes(sub)?sub:'fluxo';refreshFinance();}else{finance.classList.add('hidden');oldNav(name,sub);if(name==='gestao'&&!workPanel.classList.contains('hidden'))renderWork();}};const oldDrawerNav=window.navegarPeloDrawer;window.navegarPeloDrawer=function(name){if(name==='financeiro')return window.navegarParaSecao('financeiro');return oldDrawerNav(name);};
function installDrawer(){if($('fin-drawer'))return;const list=$('drawer-menu-lateral')?.querySelector('.overflow-y-auto');if(!list)return;const group=document.createElement('div');group.id='fin-drawer';const h=document.createElement('h4');h.textContent='Financeiro';group.append(h);for(const [key,label] of [['contas','Cadastrar contas'],['fluxo','Fluxo de caixa'],['vencimentos','Contas a pagar / receber']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.id='fin-menu-'+key;b.onclick=()=>window.navegarParaSecao('financeiro',key);group.append(b);}list.append(group);}const oldDrawer=window.reorganizarDrawerLateralDefinitivo;if(typeof oldDrawer==='function')window.reorganizarDrawerLateralDefinitivo=function(...args){const r=oldDrawer.apply(this,args);installDrawer();return r;};document.addEventListener('DOMContentLoaded',installDrawer);installDrawer();
for(const name of ['contas','fluxo','vencimentos'])$('fin-tab-'+name).onclick=()=>{active=name;refreshFinance();};$('fin-quick-account').onclick=()=>{returnToEntry=true;active='contas';refreshFinance();$('fin-back-entry').hidden=false;};$('fin-new-bill').onclick=()=>{const type=$('fin-due-type').value;active='fluxo';refreshFinance();$('fin-type').value=type;$('fin-state').value='pendente';$('fin-new').open=true;$('fin-new').scrollIntoView({block:'start'});};
function mode(){const multiple=$('fin-allocation-mode').value==='rateio';$('fin-single').hidden=multiple;$('fin-multiple').hidden=!multiple;}$('fin-allocation-mode').onchange=mode;$('fin-work').onchange=()=>{$('fin-work-hint').textContent=$('fin-work').value?'O valor será vinculado a esta obra. Informe o centro de custo.':'Sem obra: o lançamento pertence à administração.';};
$('fin-add-allocation').onclick=()=>{const row=document.createElement('div');row.className='mf-grid';const w=document.createElement('select');w.setAttribute('aria-label','Obra do rateio');opts(w,works().sort(),'Selecione a obra');const c=document.createElement('input');c.setAttribute('aria-label','Centro de custo do rateio');c.setAttribute('list','fin-centers');c.maxLength=500;const v=document.createElement('input');v.type='number';v.step='0.01';v.min='0.01';v.setAttribute('aria-label','Valor do rateio em reais');const b=document.createElement('button');b.type='button';b.textContent='Remover rateio';b.onclick=()=>row.remove();row.append(w,c,v,b);$('fin-allocations').append(row);};
function showReview(info){$('fin-review').textContent=info;$('fin-reason').value='';$('fin-payment').value=today();$('fin-reason-label').hidden=request.status!=='cancelado';$('fin-payment-label').hidden=request.status!=='pago';$('fin-dialog-status').textContent='';dialog.showModal();}
$('fin-account-save').onclick=()=>{try{const by=actor(),s=readAccounts(),rows=F.addAccount(s.data,{nome:$('fin-account-name').value,tipo:$('fin-account-type').value,banco:$('fin-account-bank').value==='Outro'?$('fin-account-bank-other').value:$('fin-account-bank').value},by);request={kind:'account',expected:s.raw,rows};showReview('Cadastrar conta de referência\n'+rows.at(-1).nome+' · '+rows.at(-1).tipo);}catch(e){$('fin-status').textContent=e.message;}};
$('fin-prepare').onclick=()=>{try{const by=actor();P.guard(localStorage,G.KEY);if(!ledger)throw Error('Atualize o fluxo antes de registrar');let rateios;if($('fin-allocation-mode').value==='rateio'){rateios=[...$('fin-allocations').children].map(r=>({obra:r.querySelector('select').value,centroCusto:r.querySelector('input[list]').value,valor:r.querySelector('input[type=number]').value}));if(!rateios.length)throw Error('Adicione as obras do rateio');}else rateios=$('fin-work').value?[{obra:$('fin-work').value,centroCusto:$('fin-center').value,valor:$('fin-value').value}]:[];const input={tipo:$('fin-type').value,status:$('fin-state').value,data:$('fin-date').value,vencimento:$('fin-due-date').value,pagoEm:$('fin-paid-date').value,empresa:$('fin-company').value,favorecido:$('fin-payee').value,categoria:$('fin-category').value,contaId:$('fin-account').value,valor:$('fin-value').value,descricao:$('fin-description').value,rateios};const entry=F.create(input,works(),readAccounts().data,by);if(!rateios.length)entry.centroCusto=$('fin-center').value.trim()||'Administrativo';request={kind:'entry',entry,expected:ledger.raw};showReview(entry.tipo.toUpperCase()+' — '+entry.descricao+'\nEmpresa: '+entry.empresa+'\nFavorecido / origem: '+entry.favorecido+'\nConta: '+entry.conta+'\nData: '+br(entry.data)+' · Vencimento: '+br(entry.vencimento)+'\nTotal: '+money(entry.valorCentavos)+' · '+entry.status+'\n'+allocationText(entry));}catch(e){$('fin-status').textContent=e.message;}};
function prepareChange(id,status){try{actor();P.guard(localStorage,G.KEY);const s=readLedger(),r=s.data.find(x=>x.id===id);if(!r)throw Error('Lançamento ausente');request={kind:'change',id,status,expected:s.raw};showReview((status==='pago'?'Registrar pagamento / recebimento':'Cancelar mantendo histórico')+'\n'+r.descricao+'\nTOTAL: '+money(r.valorCentavos)+'\nA ação abrange todos os rateios do lançamento.');}catch(e){$('fin-status').textContent=e.message;}}
$('fin-confirm').onclick=async()=>{if(busy||!request)return;busy=true;for(const el of dialog.querySelectorAll('input,button'))el.disabled=true;const req=structuredClone(request),reason=$('fin-reason').value,paidDate=$('fin-payment').value;let committed=false;try{await P.withLock(navigator.locks,()=>{const by=actor(),key=req.kind==='account'?F.ACCOUNTS:G.KEY,s=req.kind==='account'?readAccounts():readLedger();if(s.raw!==req.expected)throw Error('Dados alterados após a conferência. Atualize e confira novamente.');if(req.entry&&req.entry.criadoPor!==by||req.kind==='account'&&req.rows.at(-1).criadoPor!==by)throw Error('A sessão mudou. Reabra a conferência com o usuário atual.');let rows;if(req.kind==='account')rows=req.rows;else if(req.kind==='entry'){if(!readAccounts().data.some(x=>x.id===req.entry.contaId))throw Error('Conta indisponível');const fresh=P.snapshot(localStorage,'cm_dados_obras_v2',dadosObras).data;for(const x of req.entry.rateios)if(!Object.hasOwn(fresh,x.obra))throw Error('Obra indisponível');rows=G.append(s.data,req.entry);}else rows=G.transition(s.data,req.id,req.status,by,{reason,paidDate});P.commit(localStorage,[{key,value:rows,expected:s.raw}],{actor:by});committed=true;});dialog.close();request=null;if(req.kind==='entry'){window.martinsFormularios?.markClean($('fin-new'));for(const id of ['fin-value','fin-payee','fin-description','fin-center'])$(id).value='';$('fin-allocations').replaceChildren();$('fin-new').open=false;}if(req.kind==='account'){$('fin-account-name').value='';if(returnToEntry){active='fluxo';returnToEntry=false;}}refreshFinance();if(req.kind==='account'&&active==='fluxo'){$('fin-account').value=req.rows.at(-1).id;$('fin-new').open=true;}$('fin-back-entry').hidden=true;$('fin-status').textContent='Registro salvo. Nenhuma operação bancária foi executada.';try{window.registrarAtividadeSistema?.('Registrou operação no Financeiro '+(req.entry?.id||req.id||req.rows?.at(-1)?.id),'Financeiro');}catch{}}catch(e){$('fin-dialog-status').textContent=committed?'Registro salvo; atualize antes de repetir. '+e.message:e.message;if(P.hasPending(localStorage)){dialog.close();window.martinsMostrarRecuperacao?.();}}finally{busy=false;for(const el of dialog.querySelectorAll('input,button'))el.disabled=false;}};
$('fin-back').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{if(!busy)request=null;});
function download(report,name,content=G.csv(report)){const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('fin-export').onclick=()=>{try{actor();renderFlow();download(flowReport,'martins-fluxo-caixa.csv');}catch(e){$('fin-status').textContent=e.message;}};$('wg-export').onclick=()=>{renderWork();if(workReport)download(workReport,'martins-gastos-obra.csv',F.workCsv(workReport,$('gestao-obra-select').value));};$('fin-refresh').onclick=refreshFinance;$('fin-due-refresh').onclick=refreshFinance;$('wg-refresh').onclick=renderWork;
for(const id of ['fin-filter-type','fin-filter-company','fin-filter-work','fin-filter-category','fin-filter-center','fin-from','fin-to','fin-due-type','fin-due-state','fin-due-from','fin-due-to'])$(id).onchange=refreshFinance;for(const id of ['wg-company','wg-center','wg-from','wg-to'])$(id).onchange=renderWork;$('gestao-obra-select').addEventListener('change',()=>{if(!workPanel.classList.contains('hidden'))renderWork();});window.addEventListener('storage',e=>{if([G.KEY,F.ACCOUNTS].includes(e.key)){if(!finance.classList.contains('hidden'))refreshFinance();if(!workPanel.classList.contains('hidden'))renderWork();}});
window.addEventListener('martins-financeiro-atualizado',()=>{if(!finance.classList.contains('hidden'))refreshFinance();if(!workPanel.classList.contains('hidden'))renderWork();});
opts($('fin-category'),G.categories);opts($('fin-filter-category'),G.categories,'Todas as categorias');for(const id of ['fin-date','fin-paid-date','fin-due-date','fin-payment'])$(id).value=today();mode();
let returnToEntry=false;
$('fin-back-entry').onclick=()=>{active='fluxo';returnToEntry=false;refreshFinance();$('fin-new').open=true;$('fin-back-entry').hidden=true;};
function bankMode(){$('fin-bank-label').hidden=$('fin-account-type').value!=='Banco';$('fin-bank-other-label').hidden=$('fin-account-type').value!=='Banco'||$('fin-account-bank').value!=='Outro';}
$('fin-account-type').onchange=bankMode;$('fin-account-bank').onchange=bankMode;bankMode();
$('fin-filter-payee').oninput=refreshFinance;$('fin-due-payee').oninput=refreshFinance;
})();
